namespace CMCutLab;
internal static class Program
{
 [STAThread]static int Main(string[] args){ApplicationConfiguration.Initialize();if(args.Contains("--smoke"))return SelfTest.Smoke(args[Array.IndexOf(args,"--smoke")+1]).GetAwaiter().GetResult();if(args.Contains("--render-self-test"))return RenderTests.Run().GetAwaiter().GetResult();if(args.Contains("--self-test"))return SelfTest.Run().GetAwaiter().GetResult();using var form=new MainForm();if(args.Contains("--editor-ui-test")){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.ShowInTaskbar=false;form.TestTimeline.TestInput=true;string sample=args[Array.IndexOf(args,"--editor-ui-test")+1];form.Shown+=async(_,_)=>{await EditorUiTest.Run(form,sample);form.TestClearDirty();form.Close();};}if(args.Contains("--preview")){string sample=args[Array.IndexOf(args,"--preview")+1];form.Shown+=async(_,_)=>{await form.OpenFile(sample);var info=await Engine.Probe(sample,CancellationToken.None);form.TestContent(sample,info,[new(5,20,"テスト用候補"){Selected=true}]);await Task.Delay(2500);form.Capture(Path.Combine(AppContext.BaseDirectory,"preview.png"));form.Close();};}if(args.Contains("--open")){string initial=args[Array.IndexOf(args,"--open")+1];form.Shown+=async(_,_)=>await form.OpenFile(initial);}Application.Run(form);return 0;}
}
